// The document's types, as the contract (`logic/res/abi.json`) answers them: first generated by
// @calimero/abi-codegen from v1's ABI, kept since. The calls are the generated
// [network.calimero.pixart.generated.client.PixartClient] (`scripts/mobile-codegen.sh` at the repo
// root); until the logic derives `AbiType` the ABI names these types without their shape, so the
// client answers their JSON and [toPixart] reads it.

package network.calimero.pixart.generated

import kotlinx.serialization.KSerializer
import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import kotlinx.serialization.SerializationException
import kotlinx.serialization.descriptors.SerialDescriptor
import kotlinx.serialization.encoding.Decoder
import kotlinx.serialization.encoding.Encoder
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonDecoder
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonEncoder
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.serializer

@Serializable
data class Adjustments(
    /** -100..=100, 0 = neutral */
    val brightness: Int,
    /** -100..=100, 0 = neutral */
    val contrast: Int,
    /** -100..=100, 0 = neutral */
    val saturation: Int,
    /** -180..=180 degrees, 0 = neutral */
    val hue: Int,
    /** -100..=100, 0 = neutral */
    val exposure: Int,
    /** 0..=100 blur radius in px (filter), 0 = none */
    val blur: UInt,
    /** invert colors */
    val invert: Boolean,
    /**
     * JSON-encoded curve control points (per-channel splines). Opaque to the
     * contract; the frontend interprets it. Empty = identity curve.
     */
    val curves: String,
)

/** The owner-gated canvas settings: size and background. */
@Serializable
data class Canvas(
    val width: UInt,
    val height: UInt,
    val background: String,
)

@Serializable
data class CursorState(
    /**
     * The device this pointer belongs to (hex context key) — unique per open
     * installation, so it is what the map is keyed by.
     */
    val identity: String,
    /**
     * The member (account) behind that device, so the overlay can label the
     * pointer with a username without a second lookup table. Filled from the
     * entry's owner stamp on read, so nobody can put a pointer under someone
     * else's name.
     */
    val account: String,
    val x: Long,
    val y: Long,
    val updatedAt: ULong,
)

@Serializable
data class DocumentInfo(
    val name: String,
    val description: String,
    val width: UInt,
    val height: UInt,
    val background: String,
    val layerCount: UInt,
    val memberCount: UInt,
    val owner: String? = null,
)

/**
 * `parent_id` and `layer_index` are indexed, so a group's children and the
 * top or bottom of the stack are seeks rather than scans.
 */
@Serializable
data class Layer(
    val id: String,
    val name: String,
    /** "raster" | "group" | "text" | "adjustment" | "fill" */
    val kind: String,
    /** Parent group layer id (folder nesting); None = top level. */
    val parentId: String? = null,
    /** Order within the parent (ascending = bottom→top). */
    val layerIndex: UInt,
    val visible: Boolean,
    val locked: Boolean,
    /** 0..=100 */
    val opacity: UInt,
    /** "normal" | "multiply" | "screen" | "overlay" | "darken" | "lighten" | … */
    val blendMode: String,
    val x: Long,
    val y: Long,
    val width: UInt,
    val height: UInt,
    val rotation: Int,
    /** percent, 100 = 1:1 */
    val scaleX: Int,
    val scaleY: Int,
    /** Horizontal shear in degrees (-80..=80), 0 = none. */
    val skewX: Int,
    /** Vertical shear in degrees (-80..=80), 0 = none. */
    val skewY: Int,
    /** Mirror across the layer's vertical centre line. */
    val flipH: Boolean,
    /** Mirror across the layer's horizontal centre line. */
    val flipV: Boolean,
    /**
     * Corner-pin warp: JSON `{"tl":[dx,dy],"tr":[…],"br":[…],"bl":[…]}` in the
     * layer's own pixel units. Opaque to the contract (like `adjustments.curves`)
     * — the renderer subdivides the quad into a triangle mesh. Empty = no warp.
     */
    val warp: String,
    /** PNG pixel data for raster layers (blob id). Empty for non-raster kinds. */
    val blobId: String,
    /** Grayscale PNG layer mask (blob id). None = no mask. */
    val maskBlobId: String? = null,
    /** Solid color for `fill` layers (and a tint reference otherwise). */
    val fill: String,
    val adjustments: Adjustments,
    val text: TextProps? = null,
    val createdBy: String,
    val createdAt: ULong,
    val updatedAt: ULong,
)

@Serializable
data class Member(
    val id: String,
    val username: String,
    val avatar: String? = null,
    val joinedAt: ULong,
    /**
     * Dedicated LWW clock for username/avatar edits (joined_at never changes,
     * so merging on it would freeze a member's username at its first value).
     */
    val usernameUpdatedAt: ULong,
)

/** A member paired with their effective role, for the settings/members UI. */
@Serializable
data class MemberRole(
    val member: String,
    val role: String,
)

@Serializable
data class MeroPixArt(
    @SerialName("doc_name") val docName: String,
    @SerialName("doc_description") val docDescription: String,
    /**
     * `None` until the owner first resizes or recolours; `initial_canvas`
     * answers until then.
     */
    val canvas: Canvas,
    /**
     * What `init` was given. The `Ownable` cells above cannot be seeded at init
     * on rc.20 (the value is silently dropped — see `init`), so the opening
     * values live here and the owner-gated cells take over from the first
     * owner edit onwards. `Frozen`: written once at init, changeable by nobody,
     * so a member cannot rename the document by rewriting the fallback. Read
     * through `doc_name_str` / `canvas_now`.
     */
    @SerialName("initial_name") val initialName: String,
    @SerialName("initial_description") val initialDescription: String,
    @SerialName("initial_canvas") val initialCanvas: Canvas,
    /**
     * Writer-set guarded: only accounts holding a role mask projected from
     * `roles` (editors, admins) may write an entry, on every node.
     */
    val layers: Map<String, Layer>,
    /** One slot per account, written only by that account. */
    val members: Map<String, Member>,
    /**
     * Keyed by DEVICE, not by member — see `CursorState`. The only map here
     * that is. Each entry is owned by the account that wrote it.
     */
    val cursors: Map<String, CursorState>,
    val roles: Map<String, Boolean>,
)

@Serializable
data class TextProps(
    val content: String,
    val fontFamily: String,
    val fontSize: UInt,
    val color: String,
    val bold: Boolean,
    val italic: Boolean,
    val align: String? = null,
)

/** A 2-element tuple, a JSON array on the wire. */
@Serializable(with = ContractTuple2Serializer::class)
data class ContractTuple2<A, B>(val first: A, val second: B)

internal class ContractTuple2Serializer<A, B>(
    private val a: KSerializer<A>,
    private val b: KSerializer<B>,
) : KSerializer<ContractTuple2<A, B>> {
    override val descriptor: SerialDescriptor = JsonArray.serializer().descriptor

    override fun serialize(encoder: Encoder, value: ContractTuple2<A, B>) {
        val json = (encoder as JsonEncoder).json
        encoder.encodeJsonElement(
            JsonArray(
                listOf(
                    json.encodeToJsonElement(a, value.first),
                    json.encodeToJsonElement(b, value.second),
                ),
            ),
        )
    }

    override fun deserialize(decoder: Decoder): ContractTuple2<A, B> {
        val json = (decoder as JsonDecoder).json
        val items = decoder.decodeJsonElement().jsonArray
        if (items.size != 2) throw SerializationException("Expected 2 elements, got " + items.size)
        return ContractTuple2(
            json.decodeFromJsonElement(a, items[0]),
            json.decodeFromJsonElement(b, items[1]),
        )
    }
}

/** The JSON the contract speaks. */
val pixartJson = Json { ignoreUnknownKeys = true }

/** An answer of the generated client as the document type [T]. */
inline fun <reified T> Any.toPixart(): T = pixartJson.decodeFromJsonElement(serializer<T>(), asContractJson())

/** A value of the generated client (a typed record, or the JSON of a type the ABI does not describe) as its JSON. */
fun Any.asContractJson(): JsonElement = this as? JsonElement ?: contractArgJson.encodeToJsonElement(serializer(javaClass), this)

/** [this] (an app type) as the generated client's type [R] (an argument), through its JSON. */
inline fun <reified R> Any.asContractArg(): R = contractArgJson.decodeFromJsonElement(serializer<R>(), asContractJson())

/** The JSON between the app's types and the generated client's: every default written, unknown keys and missing options tolerated. */
val contractArgJson =
    Json {
        encodeDefaults = true
        ignoreUnknownKeys = true
        explicitNulls = false
    }
